examples.template:
VStack(spacing: theme.spacing.space3) {
    ZStack {
        RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous)
            .fill(theme.colors.accentSubtle)
            .frame(width: 40, height: 40)
        MonarchIcon(systemName: "clock", size: .md)
            .foregroundStyle(theme.colors.accentStrong)
    }
    .accessibilityHidden(true)
    MonarchBadge({{badge}}, tone: .info, variant: .outline)
    Text({{title}}).monarchTextStyle(.subheading).foregroundStyle(theme.colors.textDefault)
    Text({{description}})
        .monarchTextStyle(.body)
        .foregroundStyle(theme.colors.textMuted)
        .multilineTextAlignment(.center)
    MonarchButton({{action}}, variant: .secondary) {}
    VStack(alignment: .leading, spacing: theme.spacing.space2) {
        ForEach([{{highlights.0}}, {{highlights.1}}, {{highlights.2}}], id: \.self) { highlight in
            HStack(spacing: theme.spacing.space2) {
                Circle().fill(theme.colors.accentSolid).frame(width: 5, height: 5)
                Text(highlight).monarchTextStyle(.body).foregroundStyle(theme.colors.textDefault)
            }
        }
    }
}

